#!/bin/bash
# Starts @TOOL@ in its own tmux session, in the folder given as argument (a Windows or
# WSL path), next to a console window. Generated by the Agent Workbench setup.
TOOL="@TOOL@"
SESSION="$TOOL"

RAW_PATH="${1:-}"
START_DIR="$HOME"
if [ -n "$RAW_PATH" ]; then
    if echo "$RAW_PATH" | grep -qi 'wsl.localhost'; then
        START_DIR=$(echo "$RAW_PATH" | sed 's|\\|/|g' | sed -E 's|^//wsl\.localhost/[^/]+||i')
    elif echo "$RAW_PATH" | grep -qE '^[A-Za-z]:'; then
        START_DIR=$(wslpath -u "$RAW_PATH" 2>/dev/null || echo "$HOME")
    elif [ -d "$RAW_PATH" ]; then
        START_DIR="$RAW_PATH"
    fi
fi
[ -d "$START_DIR" ] || START_DIR="$HOME"

# The installers put the tools in different folders, not always on PATH.
CMD="$TOOL"
for c in "$HOME/.local/bin/$TOOL" "$HOME/.$TOOL/bin/$TOOL"; do [ -x "$c" ] && CMD="$c" && break; done

if tmux has-session -t "$SESSION" 2>/dev/null; then
    tmux new-window -t "$SESSION" -c "$START_DIR" "bash -ic '$CMD; exec bash'"
else
    tmux new-session -d -s "$SESSION" -c "$START_DIR" -n "$TOOL" "bash -ic '$CMD; exec bash'"
    tmux new-window -t "$SESSION" -n Console -c "$START_DIR"
    tmux select-window -t "$SESSION:$TOOL"
fi
exec tmux attach -t "$SESSION"
